import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
  type ReactNode
} from "react";
import { createPortal } from "react-dom";
import clsx from "clsx";

export type GrowlTone = "info" | "success" | "warning" | "danger";

export type GrowlOptions = {
  message: string;
  title?: string;
  tone?: GrowlTone;
  durationMs?: number;
};

type GrowlMessage = Required<GrowlOptions> & { id: string };

type GrowlContextValue = {
  showGrowl: (options: GrowlOptions) => string;
  dismissGrowl: (id: string) => void;
};

const GrowlContext = createContext<GrowlContextValue | undefined>(undefined);

const randomId = () => `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 9)}`;

export const GrowlProvider = ({ children }: { children: ReactNode }) => {
  const [messages, setMessages] = useState<GrowlMessage[]>([]);
  const timers = useRef<Record<string, number>>({});

  const clearTimer = useCallback((id: string) => {
    const handle = timers.current[id];
    if (handle) {
      window.clearTimeout(handle);
      delete timers.current[id];
    }
  }, []);

  const dismissGrowl = useCallback(
    (id: string) => {
      clearTimer(id);
      setMessages((prev) => prev.filter((message) => message.id !== id));
    },
    [clearTimer]
  );

  const showGrowl = useCallback(
    (options: GrowlOptions) => {
      const id = randomId();
      const entry: GrowlMessage = {
        id,
        title: options.title ?? "",
        message: options.message,
        tone: options.tone ?? "info",
        durationMs: options.durationMs ?? 3600
      };
      setMessages((prev) => {
        const next = [...prev, entry];
        if (next.length > 3) {
          const [removed] = next.splice(0, next.length - 3);
          if (removed) {
            clearTimer(removed.id);
          }
        }
        return next;
      });
      if (entry.durationMs > 0) {
        timers.current[id] = window.setTimeout(() => dismissGrowl(id), entry.durationMs);
      }
      return id;
    },
    [dismissGrowl, clearTimer]
  );

  const contextValue = useMemo(() => ({ showGrowl, dismissGrowl }), [showGrowl, dismissGrowl]);

  const viewport = (
    <div className="ui-growl-viewport" aria-live="assertive" aria-atomic="true">
      {[...messages].reverse().map((message) => (
        <div key={message.id} className={clsx("ui-growl", `is-${message.tone}`)}>
          <div className="ui-growl-body">
            {message.title && <p className="ui-growl-title">{message.title}</p>}
            <p className="ui-growl-message">{message.message}</p>
          </div>
          <button
            type="button"
            className="ui-growl-dismiss"
            onClick={() => dismissGrowl(message.id)}
            aria-label="Dismiss notification"
          >
            ×
          </button>
        </div>
      ))}
    </div>
  );

  const target = typeof document !== "undefined" ? document.body : null;

  return (
    <GrowlContext.Provider value={contextValue}>
      {children}
      {target ? createPortal(viewport, target) : viewport}
    </GrowlContext.Provider>
  );
};

export const useGrowl = () => {
  const context = useContext(GrowlContext);
  if (!context) {
    throw new Error("useGrowl must be used within a GrowlProvider");
  }
  return context;
};
