import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { GlassModal } from "@ui/components/GlassModal";
import { LearnIcon } from "../components/icons";
import { useTranslation } from "../i18n/I18nProvider";
import { useLearnReview } from "./useLearnReview";
import { ALL_MASTERY_FILTER, type CardMasteryFilter, type FlashOrderMode, type ReviewOrientation } from "./types";
import { LearnCard } from "./LearnCard";
import { ReviewStats } from "./ReviewStats";
import { ReviewSessionMenu } from "./ReviewSessionMenu";
import { useSessionLifecycle } from "./useSessionLifecycle";

type LearnReviewModalProps = {
  deckId?: string;
  isOpen: boolean;
  onClose: () => void;
  minCardsRequired: number;
};

export const LearnReviewModal = ({
  deckId,
  isOpen,
  onClose,
  minCardsRequired
}: LearnReviewModalProps) => {
  const { t } = useTranslation();
  const [orientation, setOrientation] = useState<ReviewOrientation>("front-first");
  const [orderMode, setOrderMode] = useState<FlashOrderMode>("random");
  const [learnLimit, setLearnLimit] = useState<number | undefined>(10);
  const [learnLimitInput, setLearnLimitInput] = useState("10");
  const [learnStarted, setLearnStarted] = useState(false);
  const [learnSessionVersion, setLearnSessionVersion] = useState(0);
  const [masteryFilter, setMasteryFilter] = useState<CardMasteryFilter>(ALL_MASTERY_FILTER);
  const [filterNotice, setFilterNotice] = useState<"none" | "insufficient" | null>(null);
  const learnStartedRef = useRef(false);
  useEffect(() => {
    learnStartedRef.current = learnStarted;
  }, [learnStarted]);

  const learnOptions = useMemo(
    () => ({
      limit: learnLimit,
      orderMode,
      masteryFilter
    }),
    [learnLimit, orderMode, masteryFilter]
  );
  const learnOptionsSignature = `${learnLimit ?? "all"}-${orderMode}-${masteryFilter.join(",")}`;
  const prevLearnOptionsSignatureRef = useRef(learnOptionsSignature);

  const learn = useLearnReview(deckId, orientation, learnOptions);
  const learnResetProgress = learn.resetProgress;
  const learnStartNewSession = learn.startNewSession;

  const deck = learn.deck;
  const filteredCards = learn.cards;
  const reviewState = learn.reviewState;
  const currentCard = learn.currentCard;
  const totalKnown = learn.totalKnown;
  const totalUnknown = learn.totalUnknown;
  const startUnknownRound = learn.startUnknownRound;

  const deckCardCount = deck?.cards.length ?? 0;
  const deckHasCards = deckCardCount > 0;
  const filteredCount = filteredCards.length;
  const hasMatchingCards = filteredCount > 0;
  const limitedCount = learnLimit ? Math.min(filteredCount, learnLimit) : filteredCount;
  const meetsDeckRequirement = deckCardCount >= minCardsRequired;
  const meetsFilteredRequirement = limitedCount >= minCardsRequired;
  const isSummary =
    reviewState != null && reviewState.currentIndex >= reviewState.cardOrder.length;
  const inProgress =
    reviewState != null &&
    reviewState.currentIndex < reviewState.cardOrder.length &&
    currentCard != null;
  const nextRoundUnknownCount = reviewState?.unknownCardIds.length ?? 0;
  const canReviewUnknown = nextRoundUnknownCount > 0;
  const question = learn.question;

  const progressLabel = useMemo(() => {
    if (!reviewState || !currentCard) {
      return undefined;
    }
    return t("review.progress", {
      current: reviewState.currentIndex + 1,
      total: reviewState.cardOrder.length
    });
  }, [reviewState, currentCard, t]);

  useEffect(() => {
    if (!isOpen) {
      setLearnStarted(false);
      setLearnSessionVersion(0);
      setLearnLimitInput(learnLimit ? String(learnLimit) : "");
      setFilterNotice(null);
    }
  }, [isOpen, learnLimit]);

  useEffect(() => {
    if (!isOpen || !hasMatchingCards) return;
    if (learnStartedRef.current) {
      setLearnStarted(false);
      setLearnSessionVersion(0);
    }
  }, [orientation, deckId, isOpen, hasMatchingCards]);

  useEffect(() => {
    if (!isOpen || !hasMatchingCards) return;
    if (!learnStartedRef.current) return;
    if (prevLearnOptionsSignatureRef.current !== learnOptionsSignature) {
      setLearnStarted(false);
      setLearnSessionVersion(0);
    }
    prevLearnOptionsSignatureRef.current = learnOptionsSignature;
  }, [learnOptionsSignature, isOpen, hasMatchingCards]);

  useEffect(() => {
    if (filterNotice && hasMatchingCards && meetsFilteredRequirement) {
      setFilterNotice(null);
    }
  }, [filterNotice, hasMatchingCards, meetsFilteredRequirement]);

  const handleLearnLimitChange = useCallback((value: string) => {
    const sanitized = value.replace(/[^\d]/g, "");
    setLearnLimitInput(sanitized);
    const parsed = sanitized ? Math.max(1, parseInt(sanitized, 10)) : undefined;
    setLearnLimit((prev) => {
      if (prev === parsed) {
        return prev;
      }
      return parsed;
    });
    setLearnStarted(false);
    setLearnSessionVersion(0);
  }, []);

  const handleLearnLimitReset = useCallback(() => {
    setLearnLimit(undefined);
    setLearnLimitInput("");
    setLearnStarted(false);
    setLearnSessionVersion(0);
  }, []);

  const handleOrderChange = useCallback((value: FlashOrderMode) => {
    if (value === orderMode) return;
    setOrderMode(value);
    setLearnStarted(false);
    setLearnSessionVersion(0);
  }, [orderMode]);

  const startLearnSession = useCallback(() => {
    if (!deckHasCards || !meetsDeckRequirement) return;
    if (!hasMatchingCards) {
      setFilterNotice("none");
      return;
    }
    if (!meetsFilteredRequirement) {
      setFilterNotice("insufficient");
      return;
    }
    setFilterNotice(null);
    setLearnStarted(true);
    setLearnSessionVersion((prev) => prev + 1);
  }, [deckHasCards, meetsDeckRequirement, hasMatchingCards, meetsFilteredRequirement]);

  useSessionLifecycle({
    isOpen,
    sessionVersion: learnSessionVersion,
    canStart: hasMatchingCards,
    onReset: learnResetProgress,
    onStart: learnStartNewSession
  });

  return (
    <GlassModal open={isOpen} onClose={onClose} panelClassName="max-w-4xl" contentClassName="text-slate-900 dark:text-slate-50">
      <header className="flex flex-wrap items-start justify-between gap-3 md:gap-4">
        <div className="space-y-2">
          <p className="flex items-center gap-2 text-xs uppercase tracking-wide text-brand-400">
            <span className="text-brand-500">
              <LearnIcon className="h-4 w-4" />
            </span>
            {t("review.mode.learnLabel")}
          </p>
          <h2 className="text-xl md:text-2xl font-semibold text-slate-900 dark:text-slate-50">
            {deck ? deck.title : t("review.selectDeck")}
          </h2>
          {deck?.description && (
            <p className="hidden md:block text-sm text-slate-700 dark:text-slate-400">{deck.description}</p>
          )}
          <p className="hidden md:block text-sm text-slate-700 dark:text-slate-500">{t("review.startDescription")}</p>
        </div>
      </header>

      {deck && !inProgress && (
        <ReviewSessionMenu
          order={{
            value: orderMode,
            onChange: handleOrderChange
          }}
          orientation={{
            value: orientation,
            onChange: setOrientation
          }}
          limit={{
            value: learnLimitInput,
            onChange: handleLearnLimitChange,
            onReset: handleLearnLimitReset
          }}
          mastery={{
            value: masteryFilter,
            onChange: (next) => {
              setMasteryFilter(next);
            }
          }}
          action={{
            label:
              learnSessionVersion > 0
                ? t("review.flash.restartButton")
                : t("review.learn.startButton"),
            disabled: !deckHasCards || !meetsDeckRequirement,
            onClick: startLearnSession
          }}
        />
      )}

      {!deckHasCards && (
        <div className="ui-empty-panel">
          {t("review.emptyDeck")}
        </div>
      )}
      {deckHasCards && !meetsDeckRequirement && (
        <div className="ui-empty-panel">
          {t("review.minCardsRequired", { count: minCardsRequired })}
        </div>
      )}
      {deckHasCards && meetsDeckRequirement && filterNotice === "none" && (
        <div className="ui-empty-panel">
          {t("review.filters.none")}
        </div>
      )}
      {deckHasCards && meetsDeckRequirement && filterNotice === "insufficient" && (
        <div className="ui-empty-panel">
          {t("review.filters.insufficient", { count: minCardsRequired })}
        </div>
      )}

      {learnStarted && inProgress && progressLabel && (
        <p className="mt-4 text-xs font-semibold uppercase tracking-wide text-brand-500">
          {progressLabel}
        </p>
      )}

      {learnStarted && inProgress && question && (
        <LearnCard
          prompt={question.prompt}
          answer={question.answer}
          options={question.options.map((o) => ({ text: o.text }))}
          onSelect={learn.handleSelect}
        />
      )}

      {isSummary && reviewState && (
        <ReviewStats
          totalCards={totalKnown + totalUnknown}
          knownCards={totalKnown}
          unknownCards={totalUnknown}
          round={reviewState.round}
          nextRoundUnknown={nextRoundUnknownCount}
          onRestartUnknown={() => {
            if (canReviewUnknown) {
              startUnknownRound?.();
            }
          }}
        />
      )}
    </GlassModal>
  );
};
