import { nanoid } from "nanoid";
import { DeckRecord } from "./types";

export type DraftCard = {
  id?: string;
  tempId: string;
  front: string;
  back: string;
  notes?: string;
};

export const createEmptyDraftCard = (): DraftCard => ({
  tempId: nanoid(),
  front: "",
  back: ""
});

export const toDraftCard = (card: DraftCard | DeckRecord["cards"][number]): DraftCard => {
  if ("tempId" in card) {
    return card;
  }
  return {
    id: card.id,
    tempId: card.id,
    front: card.front,
    back: card.back,
    ...(card.notes != null ? { notes: card.notes } : {})
  };
};
