import clsx from "clsx";
import { Button } from "@ui/components/Button";
import { useTranslation } from "../i18n/I18nProvider";
import type { FlashOrderMode, ReviewOrientation } from "./types";

type OrderSettings = {
  value: FlashOrderMode;
  onChange: (value: FlashOrderMode) => void;
};

type OrientationSettings = {
  value: ReviewOrientation;
  onChange: (value: ReviewOrientation) => void;
};

type LimitSettings = {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  label?: string;
  min?: number;
  onReset?: () => void;
  quickOptions?: number[];
};

type MasterySettings = {
  value: Array<"known" | "unsure" | "unknown" | "fresh">;
  onChange: (value: Array<"known" | "unsure" | "unknown" | "fresh">) => void;
};

const MASTERY_OPTIONS = ["known", "unsure", "unknown", "fresh"] as const;

type ReviewSessionMenuProps = {
  order?: OrderSettings;
  orientation?: OrientationSettings;
  limit?: LimitSettings;
  mastery?: MasterySettings;
  action: {
    label: string;
    disabled?: boolean;
    onClick: () => void;
  };
  className?: string;
};

export const ReviewSessionMenu = ({
  order,
  orientation,
  limit,
  mastery,
  action,
  className
}: ReviewSessionMenuProps) => {
  const { t } = useTranslation();
  const orderOptions = [
    { value: "start" as FlashOrderMode, label: t("review.flash.orderStart") },
    { value: "end" as FlashOrderMode, label: t("review.flash.orderEnd") },
    { value: "random" as FlashOrderMode, label: t("review.flash.orderRandom") }
  ];

  return (
    <div className={clsx("ui-card-panel text-sm ui-vstack-3", className)}>
      <div className="ui-flash-settings-grid">
        {order && (
          <div className="ui-flash-settings-section">
            <span className="ui-kicker">
              {t("review.flash.orderLabel")}
            </span>
            <div className="ui-flash-toggle-row">
              {orderOptions.map((option) => {
                const active = order.value === option.value;
                return (
                  <Button
                    key={option.value}
                    size="sm"
                    variant={active ? "secondary" : "outline"}
                    className={clsx(active && "ui-btn-emerald-soft")}
                    onClick={() => order.onChange(option.value)}
                  >
                    {option.label}
                  </Button>
                );
              })}
            </div>
          </div>
        )}

        {mastery && (
          <div className="ui-flash-settings-section">
            <span className="ui-kicker">
              {t("review.flash.masteryLabel")}
            </span>
            <div className="ui-flash-toggle-row">
              {MASTERY_OPTIONS.map((group) => {
                const active = mastery.value.includes(group);
                return (
                  <Button
                    key={group}
                    type="button"
                    size="sm"
                    variant={active ? "secondary" : "outline"}
                    className={clsx(active && "ui-btn-emerald-soft")}
                    onClick={() => {
                      const next = active
                        ? mastery.value.filter((item) => item !== group)
                        : [...mastery.value, group];
                      mastery.onChange(next);
                    }}
                    >
                      {t(`review.flash.mastery.${group}`)}
                    </Button>
                );
              })}
            </div>
          </div>
        )}

        {orientation && (
          <div className="ui-flash-settings-section">
            <span className="ui-kicker">
              {t("review.flash.orientationLabel")}
            </span>
            <div className="ui-flash-toggle-row">
              <Button
                size="sm"
                variant={orientation.value === "front-first" ? "secondary" : "outline"}
                className={clsx("ui-nowrap", orientation.value === "front-first" && "ui-btn-emerald-soft")}
                onClick={() => orientation.onChange("front-first")}
              >
                {t("review.cardFront")} ↦ {t("review.cardBack")}
              </Button>
              <Button
                size="sm"
                variant={orientation.value === "back-first" ? "secondary" : "outline"}
                className={clsx("ui-nowrap", orientation.value === "back-first" && "ui-btn-emerald-soft")}
                onClick={() => orientation.onChange("back-first")}
              >
                {t("review.cardBack")} ↦ {t("review.cardFront")}
              </Button>
            </div>
          </div>
        )}

        {limit && (
          <div className="flex flex-col gap-2 text-xs">
            <span className="uppercase tracking-wide text-slate-500 dark:text-slate-400">
              {limit.label ?? t("review.learn.limitLabel")}
            </span>
            <div className="flex flex-wrap gap-2">
              {(limit.quickOptions ?? [5, 10, 20, 30, 50]).map((option) => {
                const active = limit.value === String(option);
                return (
                  <Button
                    key={option}
                    type="button"
                    size="sm"
                    variant={active ? "secondary" : "outline"}
                    className={clsx(active && "ui-btn-emerald-soft")}
                    onClick={() => limit.onChange(String(option))}
                  >
                    {option}
                  </Button>
                );
              })}
              {limit.onReset && (
                <Button type="button" size="sm" variant="outline" onClick={limit.onReset}>
                  {t("review.learn.limitAll")}
                </Button>
              )}
            </div>
            <div className="flex items-center gap-2">
              <input
                type="number"
                min={limit.min ?? 1}
                inputMode="numeric"
                className="ui-input"
                value={limit.value}
                onChange={(event) => limit.onChange(event.target.value)}
                placeholder={limit.placeholder ?? t("review.learn.limitPlaceholder")}
                aria-label={limit.label ?? t("review.learn.limitLabel")}
              />
            </div>
          </div>
        )}
      </div>
      <div className="ui-flash-action-row">
        <Button
          size="sm"
          variant="secondary"
          className="ui-btn-emerald-soft"
          onClick={action.onClick}
          disabled={action.disabled}
        >
          {action.label}
        </Button>
      </div>
    </div>
  );
};
type MasteryLabelMap = {
  known: string;
  unsure: string;
  unknown: string;
  fresh: string;
};
