import { Button } from "@ui/components/Button";
import { useTranslation } from "../i18n/I18nProvider";

type AppHeaderProps = {
  isAuthenticated: boolean;
  isAuthLoading: boolean;
  onSignIn: () => void;
  onSignOut: () => void;
};

export const AppHeader = ({
  isAuthenticated,
  isAuthLoading,
  onSignIn,
  onSignOut
}: AppHeaderProps) => {
  const { t } = useTranslation();

  return (
    <header className="ui-header ui-blur-bar">
      <div className="ui-container-wide ui-header-content">
        <div className="flex items-center gap-3">
          <div className="ui-brand-badge">
            NM
          </div>
          <div className="space-y-0">
            <span className="text-lg font-semibold text-slate-900 dark:text-slate-100">
              {t("common.appName")}
            </span>
          </div>
        </div>
        <div className="ui-actions-end">
          {isAuthenticated ? (
            <div className="ui-actions-stack">
              <Button size="sm" variant="ghost" onClick={onSignOut}>
                {t("auth.signOut")}
              </Button>
            </div>
          ) : (
            <Button
              size="sm"
              disabled={isAuthLoading}
              onClick={onSignIn}
              className="ui-nowrap"
            >
              {isAuthLoading ? t("auth.loadingButton") : t("auth.signIn")}
            </Button>
          )}
        </div>
      </div>
    </header>
  );
};
