import { DeckDocument } from "@core/models";

export type DeckRecord = DeckDocument;

export type StoredDeckRecord = Omit<
  DeckRecord,
  "createdAt" | "updatedAt" | "lastSyncedAt" | "cards" | "matchResults"
> & {
  createdAt: string;
  updatedAt: string;
  lastSyncedAt?: string;
  cards: Array<
    Omit<DeckRecord["cards"][number], "createdAt" | "updatedAt" | "dueAt"> & {
      createdAt: string;
      updatedAt: string;
      dueAt: string;
    }
  >;
  matchResults: Array<
    Omit<DeckRecord["matchResults"][number], "completedAt"> & { completedAt: string }
  >;
};

export const serializeDeck = (deck: DeckRecord): StoredDeckRecord => {
  return {
    id: deck.id,
    title: deck.title,
    ...(deck.description ? { description: deck.description } : {}),
    tags: deck.tags,
    version: deck.version,
    ...(deck.driveFileId ? { driveFileId: deck.driveFileId } : {}),
    dueCardCount: deck.dueCardCount,
    createdAt: deck.createdAt.toISOString(),
    updatedAt: deck.updatedAt.toISOString(),
    ...(deck.lastSyncedAt ? { lastSyncedAt: deck.lastSyncedAt.toISOString() } : {}),
    cards: deck.cards.map((card) => ({
      id: card.id,
      deckId: card.deckId,
      front: card.front,
      back: card.back,
      ...(card.notes ? { notes: card.notes } : {}),
      interval: card.interval,
      easeFactor: card.easeFactor,
      repetition: card.repetition,
      createdAt: card.createdAt.toISOString(),
      updatedAt: card.updatedAt.toISOString(),
      dueAt: card.dueAt.toISOString()
    })),
    matchResults: (deck.matchResults ?? []).map((r) => ({
      rows: r.rows,
      cols: r.cols,
      pairs: r.pairs,
      timeMs: r.timeMs,
      mistakes: r.mistakes,
      score: r.score,
      completedAt: r.completedAt.toISOString()
    }))
  };
};

export const deserializeDeck = (stored: StoredDeckRecord): DeckRecord => {
  return {
    id: stored.id,
    title: stored.title,
    ...(stored.description ? { description: stored.description } : {}),
    tags: stored.tags,
    version: stored.version,
    ...(stored.driveFileId ? { driveFileId: stored.driveFileId } : {}),
    dueCardCount: stored.dueCardCount,
    createdAt: new Date(stored.createdAt),
    updatedAt: new Date(stored.updatedAt),
    lastSyncedAt: stored.lastSyncedAt ? new Date(stored.lastSyncedAt) : undefined,
    cards: stored.cards.map((card) => ({
      id: card.id,
      deckId: card.deckId,
      front: card.front,
      back: card.back,
      ...(card.notes ? { notes: card.notes } : {}),
      interval: card.interval,
      easeFactor: card.easeFactor,
      repetition: card.repetition,
      createdAt: new Date(card.createdAt),
      updatedAt: new Date(card.updatedAt),
      dueAt: new Date(card.dueAt)
    })),
    matchResults: (stored.matchResults ?? []).map((r) => ({
      rows: r.rows,
      cols: r.cols,
      pairs: r.pairs,
      timeMs: r.timeMs,
      mistakes: r.mistakes,
      score: r.score,
      completedAt: new Date(r.completedAt)
    }))
  };
};
