import { useCallback, useState } from "react";
import { nanoid } from "nanoid";
import type { DraftCard } from "./deckFormTypes";

type TranslateFn = (key: string, values?: Record<string, string | number>) => string;

type UseAiCardGeneratorOptions = {
  title: string;
  t: TranslateFn;
  savedAiApiKey?: string;
  setAiApiKey: (key: string) => void;
  setDraftCards: React.Dispatch<React.SetStateAction<DraftCard[]>>;
  setError: (message?: string) => void;
};

type AiCard = { front: string; back: string; notes?: string };

const sanitizeAiContent = (content: string) => {
  const stripped = content.replace(/```json|```/gi, "").trim();
  const start = stripped.indexOf("[");
  const end = stripped.lastIndexOf("]");
  if (start === -1 || end === -1 || end <= start) {
    return stripped;
  }
  return stripped.slice(start, end + 1);
};

const detectExplicitCardCount = (rawTitle: string) => {
  const match = rawTitle.match(/(\d+)/);
  if (!match) {
    return undefined;
  }
  const parsed = Number(match[1]);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return undefined;
  }
  return Math.min(parsed, 120);
};

const normalizeGeneratedCards = (parsed: unknown): DraftCard[] => {
  if (!Array.isArray(parsed)) {
    return [];
  }

  return parsed
    .map((entry) => {
      if (!entry || typeof entry !== "object") {
        return undefined;
      }
      const record = entry as Record<string, unknown>;
      const front =
        typeof record.front === "string"
          ? record.front.trim()
          : typeof record.term === "string"
            ? record.term.trim()
            : "";
      const back =
        typeof record.back === "string"
          ? record.back.trim()
          : typeof record.definition === "string"
            ? record.definition.trim()
            : typeof record.answer === "string"
              ? record.answer.trim()
              : "";
      const notes =
        typeof record.notes === "string" && record.notes.trim().length > 0
          ? record.notes.trim()
          : undefined;
      if (!front || !back) {
        return undefined;
      }
      return {
        tempId: nanoid(),
        front,
        back,
        ...(notes ? { notes } : {})
      };
    })
    .filter((card): card is DraftCard => Boolean(card));
};

export const useAiCardGenerator = ({
  title,
  t,
  savedAiApiKey,
  setAiApiKey,
  setDraftCards,
  setError
}: UseAiCardGeneratorOptions) => {
  const [aiError, setAiError] = useState<string>();
  const [isGenerating, setIsGenerating] = useState(false);

  const requestOpenAiKey = useCallback(() => {
    let key = savedAiApiKey?.trim();
    if (key) {
      return key;
    }
    if (typeof window === "undefined") {
      setAiError(t("deck.aiErrorRequest"));
      return undefined;
    }
    const provided = window.prompt(t("deck.aiPrompt"));
    if (!provided) {
      return undefined;
    }
    key = provided.trim();
    if (!key) {
      return undefined;
    }
    setAiApiKey(key);
    return key;
  }, [savedAiApiKey, setAiApiKey, t]);

  const handleGenerateWithAI = useCallback(async () => {
    if (!title.trim() || isGenerating) {
      if (!title.trim()) {
        setError(t("deck.validationTitle"));
      }
      return;
    }
    setAiError(undefined);
    const apiKey = requestOpenAiKey();
    if (!apiKey) {
      return;
    }

    setIsGenerating(true);
    const trimmedTitle = title.trim();
    const explicitCount = detectExplicitCardCount(trimmedTitle);
    const requestedCount = explicitCount ?? 25;
    const countNote = explicitCount
      ? "This exact number comes directly from the deck title; output precisely this many cards."
      : "The title contains no card count, so treat this as the default target.";
    const prompt = t("deck.aiPromptTopic", {
      title: trimmedTitle,
      count: requestedCount,
      countNote
    });

    try {
      const response = await fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${apiKey}`
        },
        body: JSON.stringify({
          model: "gpt-3.5-turbo",
          temperature: 0.4,
          messages: [
            {
              role: "system",
              content:
                "You create study flashcards. Always respond with a JSON array like [{\"front\":\"\",\"back\":\"\",\"notes\":\"optional\"}]."
            },
            {
              role: "user",
              content: prompt
            }
          ]
        })
      });

      if (!response.ok) {
        throw new Error(`status ${response.status}`);
      }

      const payload = await response.json();
      const rawContent: string | undefined = payload?.choices?.[0]?.message?.content;
      if (typeof rawContent !== "string") {
        throw new Error("missing content");
      }
      const normalized = sanitizeAiContent(rawContent);
      let parsed: unknown;
      try {
        parsed = JSON.parse(normalized);
      } catch {
        throw new Error("parse");
      }

      const generated = normalizeGeneratedCards(parsed);
      if (generated.length === 0) {
        setAiError(t("deck.aiEmpty"));
        return;
      }

      setDraftCards((prev) => [...prev, ...generated]);
      setError(undefined);
    } catch (aiErr) {
      console.error("AI generation failed", aiErr);
      if (aiErr instanceof Error && aiErr.message === "parse") {
        setAiError(t("deck.aiErrorParse"));
      } else {
        setAiError(t("deck.aiErrorRequest"));
      }
    } finally {
      setIsGenerating(false);
    }
  }, [title, isGenerating, requestOpenAiKey, t, setDraftCards, setError]);

  return {
    aiError,
    isGenerating,
    handleGenerateWithAI
  };
};
