import { nanoid } from "nanoid";
import { DeckRecord } from "./types";
import { Card } from "@core/models";

export const createCard = ({
  deckId,
  front,
  back,
  notes
}: {
  deckId: string;
  front: string;
  back: string;
  notes?: string;
}): Card => {
  const now = new Date();
  return {
    id: nanoid(),
    deckId,
    front,
    back,
    notes,
    interval: 0,
    easeFactor: 2.5,
    repetition: 0,
    dueAt: now,
    createdAt: now,
    updatedAt: now
  };
};

export const createDeckRecord = ({
  title,
  description,
  cards
}: {
  title: string;
  description?: string;
  cards: Array<{ front: string; back: string; notes?: string }>;
}): DeckRecord => {
  const deckId = nanoid();
  const now = new Date();
  const deckCards = cards.map((card) => createCard({ deckId, ...card }));

  const dueCardCount = deckCards.reduce(
    (count, card) => (card.dueAt.getTime() <= now.getTime() ? count + 1 : count),
    0
  );

  return {
    id: deckId,
    title,
    description,
    tags: [],
    createdAt: now,
    updatedAt: now,
    dueCardCount,
    cards: deckCards,
    version: 1,
    matchResults: [],
    lastSyncedAt: undefined
  };
};

const normalizeDelimiter = (delimiter?: string | null) => {
  if (!delimiter) {
    return undefined;
  }
  const trimmed = delimiter.trim();
  if (!trimmed) {
    return undefined;
  }
  const lower = trimmed.toLowerCase();
  if (lower === "\\t" || lower === "tab") {
    return "\t";
  }
  if (lower === "\\n") {
    return "\n";
  }
  return trimmed;
};

export const parseBulkInput = (
  input: string,
  preferredDelimiter?: string
): Array<{ front: string; back: string }> => {
  const lines = input
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);

  const explicitDelimiter = normalizeDelimiter(preferredDelimiter);

  return lines
    .map((line) => {
      const separator = explicitDelimiter
        ? explicitDelimiter
        : line.includes("::")
        ? "::"
        : line.includes("\t")
        ? "\t"
        : line.includes(";")
        ? ";"
        : line.includes(",")
        ? ","
        : null;
      if (!separator) {
        return null;
      }
      const [front, back] = line.split(separator);
      if (!front || !back) {
        return null;
      }
      return { front: front.trim(), back: back.trim() };
    })
    .filter((item): item is { front: string; back: string } => Boolean(item));
};
