import { createContext, ReactNode, useContext, useMemo, useCallback } from "react";
import { en } from "./locales/en";
import { Locale } from "./locales/types";
import { useDeckStore } from "../decks/useDeckStore";

type Dictionary = typeof en;

const dictionaries: Record<Locale, Dictionary> = {
  en
};

type InterpolationValues = Record<string, string | number>;

type TranslationContextValue = {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  t: (key: string, values?: InterpolationValues) => string;
};

const TranslationContext = createContext<TranslationContextValue | undefined>(undefined);

const getNestedValue = (dictionary: Dictionary, key: string): unknown => {
  return key.split(".").reduce<unknown>((acc, segment) => {
    if (acc && typeof acc === "object" && segment in acc) {
      return (acc as Record<string, unknown>)[segment];
    }
    return undefined;
  }, dictionary);
};

const interpolate = (template: string, values?: InterpolationValues) => {
  if (!values) {
    return template;
  }

  return template.replace(/\{\{(\w+)\}\}/g, (_, rawKey: string) => {
    const value = values[rawKey];
    return value != null ? String(value) : "";
  });
};

const fallbackDictionary = dictionaries.en;

export const I18nProvider = ({ children }: { children: ReactNode }) => {
  const locale = useDeckStore((state) => state.preferences.locale);
  const setLocalePreference = useDeckStore((state) => state.setLocalePreference);

  const translate = useCallback(
    (key: string, values?: InterpolationValues) => {
      const dictionary = dictionaries[locale] ?? fallbackDictionary;
      let result = getNestedValue(dictionary, key);

      if (result === undefined) {
        result = getNestedValue(fallbackDictionary, key);
      }

      if (typeof result === "string") {
        return interpolate(result, values);
      }

      // Fallback to key if path is missing
      return key;
    },
    [locale]
  );

  const value = useMemo<TranslationContextValue>(
    () => ({
      locale,
      setLocale: setLocalePreference,
      t: translate
    }),
    [locale, translate, setLocalePreference]
  );

  return <TranslationContext.Provider value={value}>{children}</TranslationContext.Provider>;
};

export const useTranslation = () => {
  const context = useContext(TranslationContext);
  if (!context) {
    throw new Error("useTranslation must be used inside I18nProvider");
  }
  return context;
};
