import { create } from "zustand";
import { createJSONStorage, persist } from "zustand/middleware";

type AuthState = {
  hydrated: boolean;
  hasAuthorized: boolean;
  status: "idle" | "loading" | "authenticated" | "error";
  accessToken?: string;
  expiresAt?: number;
  errorKey?: string;
  errorParams?: Record<string, string | number>;
  setLoading: () => void;
  setAuthenticated: (payload: { accessToken: string; expiresIn: number }) => void;
  setError: (key: string, params?: Record<string, string | number>) => void;
  signOut: () => void;
};

const STORAGE_KEY = "mova-nova-auth";

export const useAuthStore = create<AuthState>()(
  persist(
    (set) => ({
      hydrated: true,
      hasAuthorized: false,
      status: "idle",
      accessToken: undefined,
      expiresAt: undefined,
      errorKey: undefined,
      errorParams: undefined,
      setLoading: () =>
        set({
          status: "loading",
          hydrated: true,
          errorKey: undefined,
          errorParams: undefined
        }),
      setAuthenticated: ({ accessToken, expiresIn }) =>
        set({
          status: "authenticated",
          accessToken,
          expiresAt: Date.now() + expiresIn * 1000,
          hasAuthorized: true,
          hydrated: true,
          errorKey: undefined,
          errorParams: undefined
        }),
      setError: (key, params) =>
        set({
          status: "error",
          hasAuthorized: true,
          hydrated: true,
          errorKey: key,
          errorParams: params
        }),
      signOut: () =>
        set({
          status: "idle",
          accessToken: undefined,
          expiresAt: undefined,
          hasAuthorized: false,
          hydrated: true,
          errorKey: undefined,
          errorParams: undefined
        })
    }),
    {
      name: STORAGE_KEY,
      version: 1,
      storage:
        typeof window !== "undefined" ? createJSONStorage(() => window.localStorage) : undefined,
      partialize: (state) => ({
        accessToken: state.accessToken,
        expiresAt: state.expiresAt,
        hasAuthorized: state.hasAuthorized
      }),
      onRehydrateStorage: () => (persistedState) => {
        if (persistedState == null) {
          set({ hydrated: true, hasAuthorized: false });
          return;
        }

        const { accessToken, expiresAt, hasAuthorized } = persistedState as Partial<AuthState>;
        if (accessToken && typeof expiresAt === "number" && expiresAt > Date.now()) {
          set({
            status: "authenticated",
            accessToken,
            expiresAt,
            hasAuthorized: true,
            hydrated: true,
            errorKey: undefined,
            errorParams: undefined
          });
        } else {
          set({
            status: "idle",
            accessToken: undefined,
            expiresAt: undefined,
            hasAuthorized: Boolean(hasAuthorized),
            hydrated: true,
            errorKey: undefined,
            errorParams: undefined
          });
        }
      }
    }
  )
);
