import { Button } from "@ui/components/Button";
import { GlassPanel } from "@ui/components/GlassPanel";
import { useTranslation } from "../i18n/I18nProvider";

type ReviewStatsProps = {
  totalCards: number;
  knownCards: number;
  unknownCards: number;
  round: number;
  nextRoundUnknown: number;
  onRestartUnknown: () => void;
};

export const ReviewStats = ({
  totalCards,
  knownCards,
  unknownCards,
  round,
  nextRoundUnknown,
  onRestartUnknown
}: ReviewStatsProps) => {
  const { t } = useTranslation();
  const canReviewUnknown = nextRoundUnknown > 0;

  return (
    <GlassPanel className="ui-vstack-4 ui-glass-lg">
      <div className="ui-vstack-3">
        <p className="ui-kicker">
          {t("review.roundLabel", { round })}
        </p>
        <h3 className="ui-title-2xl">{t("review.summaryTitle")}</h3>
      </div>
      <ul className="ui-list-sm ui-text-sm-muted">
        <li>
          {t("review.totalCards", {
            count: totalCards
          })}
        </li>
        <li className="ui-text-success-soft">
          {t("review.knownCards", {
            count: knownCards
          })}
        </li>
        <li className="ui-text-danger-soft">
          {t("review.unknownCards", {
            count: unknownCards
          })}
        </li>
      </ul>
      {canReviewUnknown && (
        <div className="ui-actions-stack">
          <Button type="button" variant="outline" onClick={onRestartUnknown} className="ui-grow">
            {t("review.restartUnknown")}
          </Button>
        </div>
      )}
    </GlassPanel>
  );
};
