import { useCallback, useEffect, useMemo, useRef } from "react";
import {
  GOOGLE_DRIVE_SCOPES,
  initGoogleDriveTokenClient,
  TokenResponse
} from "@api-client/google-drive";
import { Capacitor } from "@capacitor/core";
import {
  GoogleAuth,
  Authentication as NativeAuthentication
} from "@codetrix-studio/capacitor-google-auth";
import { useAuthStore } from "./useAuthStore";
import { getEnv } from "../config/env";

type TokenClient = {
  requestAccessToken: (options?: { prompt?: "" | "consent" | "select_account" }) => Promise<TokenResponse>;
};

export const useGoogleDriveLogin = () => {
  const auth = useAuthStore();
  const clientRef = useRef<Promise<TokenClient>>();
  const { googleClientId, googleAndroidClientId, googleIosClientId } = getEnv();
  const isNativePlatform = Capacitor.isNativePlatform();
  const nativeScopes = useMemo(() => GOOGLE_DRIVE_SCOPES.split(" "), []);
  const nativeInitializedRef = useRef(false);
  const nativeClientId = useMemo(() => {
    if (!isNativePlatform) {
      return "";
    }
    const platform = Capacitor.getPlatform();
    if (platform === "android") {
      return googleAndroidClientId || googleClientId;
    }
    if (platform === "ios") {
      return googleIosClientId || googleClientId;
    }
    return googleClientId;
  }, [googleAndroidClientId, googleClientId, googleIosClientId, isNativePlatform]);

  const ensureClient = useCallback(async () => {
    if (!googleClientId) {
      throw new Error("Google client id is required");
    }
    if (!clientRef.current) {
      clientRef.current = initGoogleDriveTokenClient({
        clientId: googleClientId
      }).then(({ requestAccessToken }) => ({
        requestAccessToken
      }));
      console.info("[Auth] Initialized web Google token client");
    }
    return clientRef.current;
  }, [googleClientId]);

  const handleNativeInit = useCallback(() => {
    if (!isNativePlatform || nativeInitializedRef.current || !nativeClientId) {
      return;
    }
    try {
      console.info("[Auth] Initializing native Google auth", {
        platform: Capacitor.getPlatform(),
        clientId: nativeClientId,
        scopes: nativeScopes
      });
      GoogleAuth.initialize({
        clientId: nativeClientId,
        scopes: nativeScopes,
        grantOfflineAccess: false
      });
      nativeInitializedRef.current = true;
    } catch (error) {
      console.warn("Failed to initialize native Google auth", error);
    }
  }, [isNativePlatform, nativeClientId, nativeScopes]);

  useEffect(() => {
    handleNativeInit();
  }, [handleNativeInit]);

  const toTokenResponse = useCallback((authData: NativeAuthentication): TokenResponse => {
    if (!authData?.accessToken) {
      throw new Error("Missing access token from native Google auth");
    }
    return {
      access_token: authData.accessToken,
      expires_in: 3600,
      scope: GOOGLE_DRIVE_SCOPES,
      token_type: "Bearer"
    };
  }, []);

  const requestNativeAuth = useCallback(
    async (mode: "interactive" | "silent") => {
      handleNativeInit();
      if (!nativeInitializedRef.current) {
        throw new Error("Native Google auth is not initialized");
      }
      console.info("[Auth] Requesting native Google token", { mode });
      if (mode === "interactive") {
        const user = await GoogleAuth.signIn();
        console.info("[Auth] Native sign-in response", {
          hasAuth: Boolean(user?.authentication?.accessToken),
          hasIdToken: Boolean(user?.authentication?.idToken)
        });
        return user.authentication;
      }
      const authData = await GoogleAuth.refresh();
      console.info("[Auth] Native refresh response", {
        hasAuth: Boolean(authData?.accessToken),
        hasIdToken: Boolean(authData?.idToken)
      });
      return authData;
    },
    [handleNativeInit]
  );

  const requestToken = useCallback(
    async ({
      forcePrompt,
      markLoading
    }: {
      forcePrompt?: boolean;
      markLoading?: boolean;
    } = {}) => {
      if (!googleClientId || (isNativePlatform && !nativeClientId)) {
        auth.setError("auth.missingClient");
        return;
      }

      try {
        if (markLoading) {
          auth.setLoading();
        }

        if (isNativePlatform) {
          const mode = markLoading ? "interactive" : "silent";
          const nativeAuth = await requestNativeAuth(mode);
          const token = toTokenResponse(nativeAuth);
          auth.setAuthenticated({
            accessToken: token.access_token,
            expiresIn: token.expires_in
          });
          return token;
        }

        const client = await ensureClient();
        const token = await client.requestAccessToken({
          prompt: forcePrompt ? "consent" : ""
        });
        console.info("[Auth] Web Google token acquired");

        auth.setAuthenticated({
          accessToken: token.access_token,
          expiresIn: token.expires_in
        });
        return token;
      } catch (error) {
        if (markLoading) {
          auth.setError("auth.consentError");
        } else {
          console.error("Silent Google token refresh failed", error);
          void (async () => {
            if (isNativePlatform) {
              try {
                await GoogleAuth.signOut();
              } catch (signOutError) {
                console.warn("Native Google sign-out failed", signOutError);
              }
            }
            auth.signOut();
          })();
        }
      }
    },
    [auth, ensureClient, googleClientId, isNativePlatform, nativeClientId, requestNativeAuth, toTokenResponse]
  );

  const login = useCallback(
    async (options?: { forcePrompt?: boolean }) => {
      await requestToken({ forcePrompt: options?.forcePrompt, markLoading: true });
    },
    [requestToken]
  );

  const refreshToken = useCallback(async () => {
    if (!auth.hasAuthorized) {
      return;
    }
    await requestToken({ forcePrompt: false, markLoading: false });
  }, [auth.hasAuthorized, requestToken]);

  useEffect(() => {
    const expiresAt = auth.expiresAt;
    if (!expiresAt || !auth.accessToken || !auth.hasAuthorized) {
      return;
    }

    const bufferMs = 60_000; // refresh one minute before expiry
    const now = Date.now();
    const timeoutMs = Math.max(expiresAt - now - bufferMs, 0);

    if (timeoutMs === 0) {
      void refreshToken();
      return;
    }

    const id = window.setTimeout(() => {
      void refreshToken();
    }, timeoutMs);

    return () => {
      window.clearTimeout(id);
    };
  }, [auth.accessToken, auth.expiresAt, auth.hasAuthorized, refreshToken]);

  const handleSignOut = useCallback(async () => {
    if (isNativePlatform) {
      try {
        await GoogleAuth.signOut();
      } catch (error) {
        console.warn("Native Google sign-out failed", error);
      }
    }
    auth.signOut();
  }, [auth, isNativePlatform]);

  return {
    login,
    refreshToken,
    signOut: handleSignOut,
    status: auth.status,
    accessToken: auth.accessToken,
    expiresAt: auth.expiresAt,
    errorKey: auth.errorKey,
    errorParams: auth.errorParams,
    hydrated: auth.hydrated,
    hasAuthorized: auth.hasAuthorized
  };
};
